// 1. Classical acoustic Doppler frequency shifts
val fAheadRatio = if (machNumber < 1.0f) 1.0f / (1.0f - machNumber) else Float.POSITIVE_INFINITY
val fBehindRatio = 1.0f / (1.0f + machNumber)

// 2. Mach cone half-opening angle
val machAngleDeg = if (machNumber >= 1.0f) {
    asin((1.0f / machNumber).coerceIn(0f, 1f)) * (180f / PI.toFloat())
} else 0f
